import numpy as np

def get_file_table(fid):
    for f in files:
        if f['file_id'] == fid:
            return f['table']
    return None

ref = get_file_table('2026-08-03/reference_library.csv')
si_mask = (ref['material'] == 'silicon')
si_x = ref['raman_shift_cm-1'][si_mask]
si_y = ref['intensity'][si_mask]

if len(si_x) > 0:
    max_idx = np.argmax(si_y)
    print(f"Silicon global max peak: {si_x[max_idx]} cm-1 with intensity {si_y[max_idx]}")
else:
    print("No silicon data found")
